package dev.jarofcucumbers.prscraft;
import net.minecraft.nbt.CompoundTag;
/** Atomic validation shared by physical configuration, notebook templates and virtual instruments. */
public final class DeviceConfiguration{
    private DeviceConfiguration(){}
    public static void apply(RadioBlockEntity device,CompoundTag data){var next=RadioSettings.read(data);var processor=data.contains("processor")?ProcessorSettings.read(data.getCompound("processor")):device.processor();var message=data.contains("message")?MessageSettings.read(data.getCompound("message")):device.message();var gray=data.contains("gray")?GraySettings.read(data.getCompound("gray")):device.gray();var dsp=data.contains("dsp")?DspSettings.read(data.getCompound("dsp")):device.dsp();var orthogonality=data.contains("orthogonality")?OrthogonalitySettings.read(data.getCompound("orthogonality")):device.orthogonality();var protocol=data.contains("protocol")?ProtocolSettings.read(data.getCompound("protocol")):device.protocol();if(processor.demodulate()&&java.util.Set.of("unrz","urz").contains(processor.modulation())&&next.lab().amplitudeOne()<=0)throw new IllegalArgumentException("line_code");device.validateMessage(message);device.validateRadio(next);device.configureMessage(message);device.configure(next);device.configureProcessor(processor);device.configureDsp(dsp);device.configureGray(gray);device.configureProtocol(protocol);device.configureOrthogonality(orthogonality);}
    public static CompoundTag template(RadioBlockEntity radio){var tag=new CompoundTag();tag.putString("kind",radio.kind());tag.put("settings",radio.settings().save());tag.put("processor",radio.processor().save());tag.put("dsp",radio.dsp().save());tag.put("gray",radio.gray().save());tag.put("plot",radio.plot().save());tag.put("message",radio.message().save());tag.put("orthogonality",radio.orthogonality().save());tag.put("protocol",radio.protocol().save());tag.putBoolean("correlationView",radio.correlationView());tag.putInt("graphLayers",radio.graphLayers());tag.putInt("graphTerms",radio.graphTerms());return tag;}
}
